  + year : int
  + length : double
  + genre : string
}

class Artist {
  + name : string
  + dateOfBirth : date
  + websiteURL : string
}

abstract class User {
  + id : int
  + name : string
  + address : string
}

class RegularUser {
}

class BusinessUser {
  + vatNumber : string
}

class Single {
}

class Hit {
  + trackNumber : int
}

class Album {
  + title : string
}

class Suggestion {
}

User "1" -- "1" Artist : belongsTo
BusinessUser "1" -- "*" Song : uploads
Single --|> Song
Hit --|> Song
RegularUser "1" -- "*" Single : buys
RegularUser "1" -- "*" Album : composes
Album "1" *-- "1..*" Hit
RegularUser "1" -- "*" Suggestion : receives
RegularUser "1" -- "*" Suggestion : suggests
User <|-- RegularUser
User <|-- BusinessUser

@enduml

